using Xunit;

public class U21_LoggingTests
{
    [Fact]
    public void EventLog_StoresEvent_WithConfirmedVentilationSettings()
    {
        // Arrange
        var ventilationSettings = new VentilationSettings { Confirmed = true };

        // Act
        EventLog.RecordEvent(ventilationSettings);

        // Assert
        Assert.Contains(EventLog.Entries, entry => entry.VentilationSettings == ventilationSettings);
    }

    [Fact]
    public void EventLog_IncludesDateAndTimestamp()
    {
        // Act
        EventLog.RecordEvent(new VentilationSettings());

        // Assert
        Assert.All(EventLog.Entries, entry =>
        {
            Assert.NotNull(entry.Timestamp);
            Assert.NotNull(entry.Date);
        });
    }

    [Fact]
    public void EventLog_RecordsDateTimeChange()
    {
        // Arrange
        var originalDateTime = DateTime.Now;
        var newDateTime = originalDateTime.AddHours(1);

        // Act
        EventLog.RecordDateTimeChange(originalDateTime, newDateTime);

        // Assert
        Assert.Contains(EventLog.Entries, entry =>
        {
            Assert.Equal(originalDateTime, entry.OriginalDateTime);
            Assert.Equal(newDateTime, entry.NewDateTime);
        });
    }
}
